'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset" // Power BI Data
  },
  "facet": {
    // Y-axis categories
    "row": {
      "field": "Category",
      "type": "nominal",
      "labels": false,
      "title": "",
      "sort": {
        "field": "Venta Neta AA",
        "order": "descending"
      },

      // Might move to config?
      "header": {
        "labelAngle": 0,
        "title": null,
        "labelAlign": "left",
        "labelPadding": 5
      }
    }
  },
  "spec": {
    "layer": [
      {
        // Bars to show the actual
        "mark": {"type": "bar", "color": "#48B8DE", "size": 30, "opacity": 1},
        "encoding": {
          "x": {"field": "Venta Neta AA", "type": "quantitative","title": null,"labels": false}
        }
      },
      {
        // Bars to show the actual
        "mark": {"type": "bar", "color": "#D4DAE0", "size": 20, "opacity": 1},
        "encoding": {
          "x": {"field": "Venta Netas PY","title": null,"labels": null, "type": "quantitative"}
        }
      },
      {
        // Circles to indicate action dots
        "mark": {"type": "point" },
        "encoding": {
          "x": {"value": -10},
          "color": {
            "condition": [
              {
                // Bad
                "test": "datum[''Margen'']> 0 ",
                "value": "#333333"
              },
              {
                // good
                "test": "datum[''Margen''] < 0 ",
                "value": "#F13737"
              }
            ],
            "value": null  // No dot if within 96%-105%
          },
          "size": {
            "condition": [
              {
                // Very bad
                "test": "datum[''Margen''] < 0 ",
                "value": 125
              },
              {
                // Very good
                "test": "datum[''Margen''] > 0  ",
                "value": 125
              }
            ],
            "value": 0  // No dot if within 96%-105%
          }
          ,
          "shape": {
            "condition": [
              {
                // Very bad
                "test": "datum[''Margen''] < 0 ",
                "value": "triangle-down"
              },
              {
                // Very good
                "test": "datum[''Margen''] > 0  ",
                "value": "triangle-up"
              }
            ],
            "value": 0  // No dot if within 96%-105%
          }
        }
      },
      {
        // Actuals label (between dot and bar)
        "mark": {"type": "text", "align": "right", "dx": -5},
        "encoding": {
          "x": {"value": -15},
          "text": {"field": "Margen", "type": "quantitative", "format": ".1%"},
          "color": {
            "condition": [
              {
                //  bad
                "test": "datum[''Margen'']< 0 ",
                "value": "#F13737"
              },
              {
                // good
                "test": "datum[''Margen'']> 0 ",
                "value": "#333333"
              }
            ],
            "value": "#5d5d5d"  // No dot if within 96%-105%
          }
        }
      },
      {
        // Target label (on top of tick)
        "mark": {"type": "text", "align": "center", "dy": 0,"dx": 35},
        "encoding": {
          "x": {"field": "Venta Netas PY", "type": "quantitative","title": null},
          "text": {"field": "Venta Netas PY", "type": "quantitative","title": null, "format": ",.3s"},
          "color": {"value": "#333333"},
          "size": {"value": 10},
          "labels": false
        }
      }
    ]
  }
}'

'{
    "autosize": {
      "type": "fit",
      "contains": "padding"
    },
    "view": {"stroke": "transparent"},
    "font": "Segoe UI",
    "arc": {},
    "area": {
      "line": true,
      "opacity": 0.6
    },
    "bar": {},
    "line": {
      "strokeWidth": 2,
      "strokeCap": "round",
      "strokeJoin": "round"
    },
    "path": {},
    "point": {
      "filled": true,
      "size": 75
    },
    "rect": {},
    "shape": {},
    "symbol": {},
    "text": {
      "font": "Segoe UI Light",
      "fontSize": 12,
      "fill": "#AAAAAA"
    },
    "axis": {
      "ticks": false,
      "labels": false,
      "grid": false,
      "domain": false,
      "labelColor": "#AAAAAA",
      "labelFontSize": 12,
      "titleFont": "Segoe UI Light",
      "titleColor": "#FFFFFF",
      "titleFontSize": 10
    },
    "axisQuantitative": {
      "tickCount": 5,
      "grid": false,
      "gridColor": "#CCCCCC",
      "gridDash": [1, 3],
      "labelFlush": false
    },
    "axisX": {"labelPadding": 2.5},
    "header": {
      "labelFont": "Segoe UI Semibold",
      "labelFontSize": 9,
      "labelColor": "#5D5D5D"
    },
    "tick": {"thickness": 1.5},
    "facet": {
      "spacing": 7.5  // Spacing between categories
    }
  }'
